chrome.runtime.sendMessage = function(msg, callback) {
  let retryCount = 0;
  function attempt() {
    _originalSendMessage(msg, (res) => {
      const err = chrome.runtime.lastError;
      if (err && err.message && err.message.includes('Receiving end does not exist')) {
        if (retryCount < 3) {
          console.warn('[Popup] Wake-up retry', retryCount + 1, 'for message:', msg.type);
          retryCount++;
          setTimeout(attempt, 300);
          return;
        }
      }
      if (callback) callback(res);
    });
  }
  attempt();
};
